const crypto = require('crypto');
const root = $input.item.json || {};
const body = root.body;
const TEMPLATE_VERSION = 'CLIENT_REPORT_V1_2026-09-01';
const nowMs = Date.now();
const nowUtc = new Date(nowMs).toISOString();
const MAX_SOURCE_AGE_MS = 93 * 24 * 60 * 60 * 1000;
const hash = (value) => crypto.createHash('sha256').update(String(value), 'utf8').digest('hex');
const isRecord = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const exactKeys = (object, expected) => {
  if (!isRecord(object)) return false;
  const actual = Object.keys(object).sort();
  const wanted = [...expected].sort();
  return actual.length === wanted.length && actual.every((key, index) => key === wanted[index]);
};
const stable = (value) => {
  if (Array.isArray(value)) return '[' + value.map(stable).join(',') + ']';
  if (isRecord(value)) return '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + stable(value[key])).join(',') + '}';
  return JSON.stringify(value);
};
const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (character) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
})[character]);
const strictString = (value, min, max, pattern) => typeof value === 'string'
  && value === value.trim()
  && !/[\u0000-\u001F\u007F]/.test(value)
  && value.length >= min
  && value.length <= max
  && (!pattern || pattern.test(value));
const emailPattern = /^[A-Za-z0-9.!#$%&'*+/=?^_{\x60|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+$/;
const reportKeys = [
  'tenant_id', 'source_report_id', 'report_period', 'client_name', 'recipient_email',
  'verified_recipient_email', 'locale', 'brand_name', 'brand_color',
  'source_updated_at_utc', 'source_status', 'metrics', 'highlights', 'risks', 'next_steps',
];
const metricKeys = ['leads', 'qualified_leads', 'proposals', 'won_deals', 'revenue_minor', 'currency'];
const batchErrors = [];
if (!isRecord(body)) batchErrors.push('body_must_be_object');
else if (!exactKeys(body, ['batch_id', 'reports'])) batchErrors.push('body_keys_must_be_exact_batch_id_and_reports');
const batchId = isRecord(body) && strictString(body.batch_id, 1, 80, /^[A-Za-z0-9][A-Za-z0-9._-]*$/) ? body.batch_id : '';
if (isRecord(body) && !batchId) batchErrors.push('invalid_batch_id');
const rawReports = isRecord(body) && Array.isArray(body.reports) ? body.reports : [];
if (isRecord(body) && (!Array.isArray(body.reports) || body.reports.length < 1 || body.reports.length > 20)) {
  batchErrors.push('reports_must_contain_1_to_20_items');
}
const reports = rawReports.slice(0, 20).map((raw, inputIndex) => {
  const errors = [];
  if (!isRecord(raw)) errors.push('report_must_be_object');
  if (isRecord(raw) && !exactKeys(raw, reportKeys)) errors.push('report_keys_must_match_exact_contract');
  const source = isRecord(raw) ? raw : {};
  const checkString = (key, min, max, pattern) => {
    const valid = strictString(source[key], min, max, pattern);
    if (!valid) errors.push('invalid_' + key);
    return valid ? source[key] : '';
  };
  const tenantId = checkString('tenant_id', 1, 64, /^[a-z0-9][a-z0-9_-]*$/);
  const sourceReportId = checkString('source_report_id', 1, 128, /^[A-Za-z0-9][A-Za-z0-9._:-]*$/);
  const reportPeriod = checkString('report_period', 7, 7, /^\d{4}-(0[1-9]|1[0-2])$/);
  const clientName = checkString('client_name', 1, 120);
  const recipientRaw = checkString('recipient_email', 3, 254, emailPattern);
  const verifiedRaw = checkString('verified_recipient_email', 3, 254, emailPattern);
  const recipientEmail = recipientRaw.toLowerCase();
  const verifiedRecipientEmail = verifiedRaw.toLowerCase();
  if (recipientEmail && verifiedRecipientEmail && recipientEmail !== verifiedRecipientEmail) errors.push('verified_recipient_email_mismatch');
  const locale = checkString('locale', 5, 5, /^(en-US|pl-PL)$/);
  const brandName = checkString('brand_name', 1, 100);
  const brandColor = checkString('brand_color', 7, 7, /^#[0-9A-Fa-f]{6}$/).toUpperCase();
  const sourceStatus = checkString('source_status', 8, 16, /^(complete|complete_no_data)$/);
  const sourceTimestampRaw = checkString('source_updated_at_utc', 20, 35, /(?:Z|[+-]\d{2}:\d{2})$/);
  const sourceMs = Date.parse(sourceTimestampRaw);
  let sourceUpdatedAtUtc = '';
  if (!Number.isFinite(sourceMs)) errors.push('invalid_source_updated_at_utc');
  else {
    sourceUpdatedAtUtc = new Date(sourceMs).toISOString();
    if (sourceMs > nowMs) errors.push('source_updated_at_utc_must_not_be_future');
    if (nowMs - sourceMs > MAX_SOURCE_AGE_MS) errors.push('source_updated_at_utc_is_stale');
  }
  const validateArray = (key) => {
    const value = source[key];
    if (!Array.isArray(value) || value.length > 12) {
      errors.push('invalid_' + key + '_array');
      return [];
    }
    const normalized = [];
    for (const entry of value) {
      if (!strictString(entry, 1, 300)) errors.push('invalid_' + key + '_entry');
      else normalized.push(entry);
    }
    return normalized;
  };
  const highlights = validateArray('highlights');
  const risks = validateArray('risks');
  const nextSteps = validateArray('next_steps');
  const metrics = isRecord(source.metrics) ? source.metrics : null;
  let normalizedMetrics = {};
  if (sourceStatus === 'complete') {
    if (!metrics || !exactKeys(metrics, metricKeys)) errors.push('complete_metrics_keys_must_match_exact_contract');
    else {
      const integerKeys = metricKeys.slice(0, 5);
      for (const key of integerKeys) {
        const value = metrics[key];
        if (typeof value !== 'number' || !Number.isFinite(value) || !Number.isSafeInteger(value) || value < 0) {
          errors.push('invalid_metric_' + key);
        }
      }
      if (!strictString(metrics.currency, 3, 3, /^[A-Z]{3}$/)) errors.push('invalid_metric_currency');
      if (!errors.some((error) => error.startsWith('invalid_metric_'))) {
        if (!(metrics.leads >= metrics.qualified_leads
          && metrics.qualified_leads >= metrics.proposals
          && metrics.proposals >= metrics.won_deals)) {
          errors.push('metrics_funnel_order_invalid');
        }
        normalizedMetrics = {
          leads: metrics.leads,
          qualified_leads: metrics.qualified_leads,
          proposals: metrics.proposals,
          won_deals: metrics.won_deals,
          revenue_minor: metrics.revenue_minor,
          currency: metrics.currency,
