  } else if (!metrics) {
    errors.push('metrics_must_be_object');
  }
  return {
    input_index: inputIndex,
    valid_input: errors.length === 0,
    validation_errors: [...new Set(errors)].sort(),
    tenant_id: tenantId,
    source_report_id: sourceReportId,
    report_period: reportPeriod,
    client_name: clientName,
    recipient_email: recipientEmail,
    verified_recipient_email: verifiedRecipientEmail,
    locale,
    brand_name: brandName,
    brand_color: brandColor,
    source_updated_at_utc: sourceUpdatedAtUtc,
    source_status: sourceStatus,
    metrics: normalizedMetrics,
    highlights,
    risks,
    next_steps: nextSteps,
  };
});
const scopeIndexes = new Map();
for (const report of reports) {
  if (!report.tenant_id || !report.report_period) continue;
  const scope = report.tenant_id + '\n' + report.report_period;
  const indexes = scopeIndexes.get(scope) || [];
  indexes.push(report.input_index);
  scopeIndexes.set(scope, indexes);
}
for (const indexes of scopeIndexes.values()) {
  if (indexes.length < 2) continue;
  for (const index of indexes) {
    reports[index].validation_errors.push('duplicate_tenant_period_scope_in_batch');
    reports[index].validation_errors.sort();
