}
const labels = {
  'en-US': {
    title: 'Client performance report', performance: 'Performance', highlights: 'Highlights',
    risks: 'Risks', next: 'Next steps', source: 'Source metadata', none: 'None reported.',
    noData: 'No source data was supplied for this reporting period.',
    metricNames: ['Leads', 'Qualified leads', 'Proposals', 'Won deals', 'Revenue'],
    subject: 'client report draft',
  },
  'pl-PL': {
    title: 'Raport wyników klienta', performance: 'Wyniki', highlights: 'Najważniejsze informacje',
    risks: 'Ryzyka', next: 'Następne kroki', source: 'Metadane źródłowe', none: 'Brak zgłoszonych pozycji.',
    noData: 'Dla tego okresu raportowego nie dostarczono danych źródłowych.',
