  },
};
const listHtml = (title, values, label) => '<section><h2>' + escapeHtml(title) + '</h2>'
  + (values.length ? '<ul>' + values.map((value) => '<li>' + escapeHtml(value) + '</li>').join('') + '</ul>' : '<p>' + escapeHtml(label) + '</p>')
  + '</section>';
for (const report of reports) {
