const batch = $items('Normalize Client Report Batch')[0].json;
const physicalRows = $input.all().map((item) => item.json || {}).filter((row) => typeof row.report_scope_key === 'string');
const decisions = [];
const newReports = [];
for (const report of batch.reports.filter((candidate) => candidate.valid_input)) {
  const rows = physicalRows.filter((row) => row.report_scope_key === report.report_scope_key);
  let action = 'new_intent';
  if (rows.length >= 2) action = 'ambiguous_physical_rows';
  else if (rows.length === 1) {
    const row = rows[0];
    if (row.report_fingerprint !== report.report_fingerprint) action = 'identity_conflict';
    else if (row.lifecycle_status === 'Draft Ready' && typeof row.gmail_draft_id === 'string' && row.gmail_draft_id.length > 0) action = 'terminal_replay';
