const decisionBatch = $input.item.json;
const batch = $items('Normalize Client Report Batch')[0].json;
const nowUtc = new Date().toISOString();
return decisionBatch.new_reports.map((report) => ({
  json: {
    ...report,
    batch_id: batch.batch_id,
    lifecycle_status: 'Draft Intent',
    gmail_draft_id: '',
    gmail_thread_id: '',
    gmail_error: '',
    created_at_utc: nowUtc,
    updated_at_utc: nowUtc,
    execution_id: $execution.id,
  },
