const intents = $items('Expand New Draft Intents').map((item) => item.json);
const rows = $input.all().map((item) => item.json || {});
const draftJobs = [];
const intentResults = [];
for (const intent of intents) {
  const matches = rows.filter((row) => row.report_scope_key === intent.report_scope_key
    && row.report_fingerprint === intent.report_fingerprint
    && row.lifecycle_status === 'Draft Intent');
  const acknowledged = matches.length === 1;
  intentResults.push({
    input_index: intent.input_index,
    report_scope_key: intent.report_scope_key,
    report_fingerprint: intent.report_fingerprint,
    acknowledgement_count: matches.length,
