  json: {
    input_index: job.input_index,
    report_scope_key: job.report_scope_key,
    report_fingerprint: job.report_fingerprint,
    lifecycle_status: draftId ? 'Draft Ready' : 'Draft Pending Reconcile',
    gmail_draft_id: draftId,
    gmail_thread_id: threadId,
    gmail_error: gmailError,
