  const matches = rows.filter((row) => row.report_scope_key === update.report_scope_key
    && row.report_fingerprint === update.report_fingerprint
    && row.lifecycle_status === update.lifecycle_status
    && String(row.gmail_draft_id || '') === update.gmail_draft_id
    && String(row.gmail_thread_id || '') === update.gmail_thread_id);
  const acknowledged = matches.length === 1;
  draftResults.push({
    input_index: update.input_index,
    report_scope_key: update.report_scope_key,
    report_fingerprint: update.report_fingerprint,
    lifecycle_status: update.lifecycle_status,
    acknowledgement_count: matches.length,
